CREATE TABLE public.devolucoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),controle bigint GENERATED ALWAYS AS IDENTITY UNIQUE,comprovante_id uuid NOT NULL UNIQUE REFERENCES public.comprovantes(id),nota_origem_id uuid REFERENCES public.notas_fiscais(id),numero_nf text NOT NULL DEFAULT '',data_documento date,documental text NOT NULL DEFAULT 'pendente' CHECK(documental IN ('pendente','tratada')),prestacao text NOT NULL DEFAULT 'pendente' CHECK(prestacao IN ('pendente','enviada')),enviada_em timestamptz,enviada_por uuid REFERENCES public.profiles(id),observacoes text NOT NULL DEFAULT '',versao integer NOT NULL DEFAULT 1,created_by uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.devolucoes TO authenticated; GRANT ALL ON public.devolucoes TO service_role; ALTER TABLE public.devolucoes ENABLE ROW LEVEL SECURITY; CREATE POLICY returns_office_read ON public.devolucoes FOR SELECT TO authenticated USING(private.can_write(auth.uid()));
CREATE TABLE public.devolucao_itens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),devolucao_id uuid NOT NULL REFERENCES public.devolucoes(id),item_numero text NOT NULL,codigo text NOT NULL,descricao text NOT NULL,quantidade_original numeric NOT NULL,unidade_original text NOT NULL,quantidade numeric NOT NULL CHECK(quantidade>0),unidade text NOT NULL,motivo text NOT NULL,lote text NOT NULL DEFAULT '',validade date,observacoes text NOT NULL DEFAULT '',retorno_fisico boolean NOT NULL DEFAULT true,ativo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.devolucao_itens TO authenticated; GRANT ALL ON public.devolucao_itens TO service_role; ALTER TABLE public.devolucao_itens ENABLE ROW LEVEL SECURITY; CREATE POLICY return_items_read ON public.devolucao_itens FOR SELECT TO authenticated USING(private.can_write(auth.uid()));
CREATE TABLE public.devolucao_pallets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),devolucao_id uuid NOT NULL REFERENCES public.devolucoes(id),numero integer NOT NULL CHECK(numero>0),localizacao text NOT NULL DEFAULT '',created_by uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(devolucao_id,numero));
GRANT SELECT ON public.devolucao_pallets TO authenticated; GRANT ALL ON public.devolucao_pallets TO service_role; ALTER TABLE public.devolucao_pallets ENABLE ROW LEVEL SECURITY; CREATE POLICY return_pallets_read ON public.devolucao_pallets FOR SELECT TO authenticated USING(private.can_write(auth.uid()));
CREATE TABLE public.devolucao_alocacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pallet_id uuid NOT NULL REFERENCES public.devolucao_pallets(id),item_id uuid NOT NULL REFERENCES public.devolucao_itens(id),quantidade numeric NOT NULL CHECK(quantidade>0),created_by uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(pallet_id,item_id));
GRANT SELECT ON public.devolucao_alocacoes TO authenticated; GRANT ALL ON public.devolucao_alocacoes TO service_role; ALTER TABLE public.devolucao_alocacoes ENABLE ROW LEVEL SECURITY; CREATE POLICY return_allocations_read ON public.devolucao_alocacoes FOR SELECT TO authenticated USING(private.can_write(auth.uid()));
CREATE TABLE public.devolucao_reservas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),item_id uuid NOT NULL REFERENCES public.devolucao_itens(id),pallet_id uuid REFERENCES public.devolucao_pallets(id),coleta_ref uuid,quantidade numeric NOT NULL CHECK(quantidade>0),status text NOT NULL DEFAULT 'ativa' CHECK(status IN ('ativa','liberada','retirada')),motivo text NOT NULL,registrado_por uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.devolucao_reservas TO authenticated; GRANT ALL ON public.devolucao_reservas TO service_role; ALTER TABLE public.devolucao_reservas ENABLE ROW LEVEL SECURITY; CREATE POLICY return_reservations_read ON public.devolucao_reservas FOR SELECT TO authenticated USING(private.can_write(auth.uid()));
CREATE TABLE public.devolucao_movimentos(id uuid PRIMARY KEY, item_id uuid NOT NULL REFERENCES public.devolucao_itens(id),pallet_id uuid REFERENCES public.devolucao_pallets(id),reserva_id uuid REFERENCES public.devolucao_reservas(id),tipo text NOT NULL CHECK(tipo IN ('entrada','saida')),quantidade numeric NOT NULL CHECK(quantidade>0),unidade text NOT NULL,data_movimento timestamptz NOT NULL DEFAULT now(),motivo text NOT NULL,retirado_por text NOT NULL DEFAULT '',observacoes text NOT NULL DEFAULT '',registrado_por uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX return_single_receipt ON public.devolucao_movimentos(item_id) WHERE tipo='entrada';
GRANT SELECT ON public.devolucao_movimentos TO authenticated; GRANT ALL ON public.devolucao_movimentos TO service_role; ALTER TABLE public.devolucao_movimentos ENABLE ROW LEVEL SECURITY; CREATE POLICY return_movements_read ON public.devolucao_movimentos FOR SELECT TO authenticated USING(private.can_write(auth.uid()));
CREATE OR REPLACE FUNCTION public.tratar_devolucao(_documento uuid,_dados jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d devolucoes; p comprovantes; n notas_fiscais; x jsonb; fiscal jsonb; uid uuid:=auth.uid(); nid uuid; BEGIN IF NOT private.can_write(uid) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO p FROM comprovantes WHERE id=_documento FOR UPDATE; IF NOT FOUND OR p.tipo_documento<>'devolucao' OR p.triagem<>'analisado' THEN RAISE EXCEPTION 'Confirme a classificação como nota de devolução'; END IF; SELECT * INTO d FROM devolucoes WHERE comprovante_id=_documento FOR UPDATE; nid:=nullif(_dados->>'nota_origem_id','')::uuid; IF d.id IS NOT NULL THEN IF EXISTS(SELECT 1 FROM devolucao_movimentos m JOIN devolucao_itens i ON i.id=m.item_id WHERE i.devolucao_id=d.id) OR d.prestacao='enviada' THEN RAISE EXCEPTION 'Tratamento preservado após recebimento ou prestação de contas'; END IF; IF (_dados->>'versao')::int IS DISTINCT FROM d.versao THEN RAISE EXCEPTION 'Devolução alterada por outra pessoa; atualize'; END IF; END IF; IF nid IS NOT NULL THEN SELECT * INTO n FROM notas_fiscais WHERE id=nid; IF NOT FOUND THEN RAISE EXCEPTION 'Nota de origem não encontrada'; END IF; END IF; IF coalesce(_dados->>'documental','pendente')='tratada' AND (nid IS NULL OR trim(coalesce(_dados->>'numero_nf',''))='' OR jsonb_array_length(coalesce(_dados->'itens','[]'))=0) THEN RAISE EXCEPTION 'Informe NF de devolução, origem e produtos'; END IF; IF d.id IS NULL THEN INSERT INTO devolucoes(comprovante_id,created_by) VALUES(_documento,uid) RETURNING * INTO d; ELSE UPDATE devolucao_itens SET ativo=false WHERE devolucao_id=d.id AND ativo; END IF; UPDATE devolucoes SET nota_origem_id=nid,numero_nf=coalesce(_dados->>'numero_nf',''),data_documento=nullif(_dados->>'data_documento','')::date,documental=coalesce(_dados->>'documental','pendente'),observacoes=coalesce(_dados->>'observacoes',''),versao=versao+1,updated_at=now() WHERE id=d.id; FOR x IN SELECT value FROM jsonb_array_elements(coalesce(_dados->'itens','[]')) LOOP SELECT value INTO fiscal FROM jsonb_array_elements(n.itens_xml) WHERE value->>'numero'=x->>'item_numero'; IF fiscal IS NULL THEN RAISE EXCEPTION 'Produto inexistente no XML da nota de origem'; END IF; IF trim(coalesce(x->>'unidade',''))='' OR trim(coalesce(x->>'motivo',''))='' THEN RAISE EXCEPTION 'Informe unidade e motivo por item'; END IF; IF x->>'motivo'='falta' AND coalesce((x->>'retorno_fisico')::boolean,true) THEN RAISE EXCEPTION 'Falta não cria retorno físico'; END IF; INSERT INTO devolucao_itens(devolucao_id,item_numero,codigo,descricao,quantidade_original,unidade_original,quantidade,unidade,motivo,lote,validade,observacoes,retorno_fisico) VALUES(d.id,fiscal->>'numero',fiscal->>'codigo',fiscal->>'descricao',(fiscal->>'quantidade')::numeric,fiscal->>'unidade',(x->>'quantidade')::numeric,upper(trim(x->>'unidade')),x->>'motivo',coalesce(x->>'lote',''),nullif(x->>'validade','')::date,coalesce(x->>'observacoes',''),coalesce((x->>'retorno_fisico')::boolean,true)); END LOOP; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('devolucao',d.id,'tratamento',coalesce(_dados->>'documental','pendente'),uid); RETURN d.id; END $$;
REVOKE ALL ON FUNCTION public.tratar_devolucao(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.tratar_devolucao(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.prestar_contas_devolucao(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d devolucoes; BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO d FROM devolucoes WHERE id=_id FOR UPDATE; IF d.documental IS DISTINCT FROM 'tratada' THEN RAISE EXCEPTION 'Trate os produtos antes de enviar'; END IF; IF d.prestacao='enviada' THEN RETURN; END IF; UPDATE devolucoes SET prestacao='enviada',enviada_em=now(),enviada_por=auth.uid(),updated_at=now(),versao=versao+1 WHERE id=_id; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('devolucao',_id,'enviada_fornecedor','Informações enviadas; sem baixa física',auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.prestar_contas_devolucao(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.prestar_contas_devolucao(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.movimentar_devolucao(_operacao uuid,_item uuid,_tipo text,_quantidade numeric,_dados jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i devolucao_itens; d devolucoes; saldo numeric; reservado numeric; pal uuid:=nullif(_dados->>'pallet_id','')::uuid; res uuid:=nullif(_dados->>'reserva_id','')::uuid; r devolucao_reservas; available numeric; previous devolucao_movimentos; BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO i FROM devolucao_itens WHERE id=_item FOR UPDATE; IF NOT FOUND OR NOT i.ativo OR NOT i.retorno_fisico THEN RAISE EXCEPTION 'Item sem retorno físico'; END IF; SELECT * INTO d FROM devolucoes WHERE id=i.devolucao_id FOR UPDATE; SELECT * INTO previous FROM devolucao_movimentos WHERE id=_operacao; IF FOUND THEN IF previous.item_id<>_item OR previous.tipo<>_tipo OR previous.quantidade<>_quantidade OR previous.pallet_id IS DISTINCT FROM pal THEN RAISE EXCEPTION 'Operação reutilizada com dados diferentes'; END IF; RETURN _operacao; END IF; IF _quantidade IS NULL OR _quantidade<=0 THEN RAISE EXCEPTION 'Quantidade inválida'; END IF; IF _tipo NOT IN ('entrada','saida') THEN RAISE EXCEPTION 'Movimento inválido'; END IF; IF d.documental<>'tratada' THEN RAISE EXCEPTION 'Tratamento pendente'; END IF; IF _tipo='entrada' THEN IF EXISTS(SELECT 1 FROM devolucao_movimentos WHERE item_id=_item AND tipo='entrada') THEN RAISE EXCEPTION 'Recebimento já registrado'; END IF; IF _quantidade>i.quantidade THEN RAISE EXCEPTION 'Recebimento superior à quantidade tratada'; END IF; IF pal IS NOT NULL THEN RAISE EXCEPTION 'Atribua pallet após receber'; END IF; ELSE IF d.prestacao<>'enviada' THEN RAISE EXCEPTION 'Prestação de contas pendente'; END IF; IF trim(coalesce(_dados->>'retirado_por',''))='' OR trim(coalesce(_dados->>'motivo',''))='' THEN RAISE EXCEPTION 'Informe quem retirou e o motivo'; END IF; SELECT coalesce(sum(CASE WHEN tipo='entrada' THEN quantidade ELSE -quantidade END),0) INTO saldo FROM devolucao_movimentos WHERE item_id=_item; IF res IS NOT NULL THEN SELECT * INTO r FROM devolucao_reservas WHERE id=res AND item_id=_item FOR UPDATE; IF NOT FOUND OR r.status<>'ativa' OR r.quantidade<>_quantidade OR r.pallet_id IS DISTINCT FROM pal THEN RAISE EXCEPTION 'Reserva inválida'; END IF; END IF; SELECT coalesce(sum(quantidade),0) INTO reservado FROM devolucao_reservas WHERE item_id=_item AND status='ativa' AND id IS DISTINCT FROM res; IF _quantidade>saldo-reservado THEN RAISE EXCEPTION 'Saída superior ao saldo disponível'; END IF; IF pal IS NOT NULL THEN SELECT a.quantidade-coalesce((SELECT sum(quantidade) FROM devolucao_movimentos WHERE item_id=_item AND pallet_id=pal AND tipo='saida'),0)-coalesce((SELECT sum(quantidade) FROM devolucao_reservas WHERE item_id=_item AND pallet_id=pal AND status='ativa' AND id IS DISTINCT FROM res),0) INTO available FROM devolucao_alocacoes a WHERE item_id=_item AND pallet_id=pal; IF available IS NULL OR _quantidade>available THEN RAISE EXCEPTION 'Saldo insuficiente neste pallet'; END IF; ELSE IF EXISTS(SELECT 1 FROM devolucao_alocacoes WHERE item_id=_item) THEN RAISE EXCEPTION 'Escolha o pallet da retirada'; END IF; END IF; END IF; INSERT INTO devolucao_movimentos(id,item_id,pallet_id,reserva_id,tipo,quantidade,unidade,data_movimento,motivo,retirado_por,observacoes,registrado_por) VALUES(_operacao,_item,pal,res,_tipo,_quantidade,i.unidade,coalesce(nullif(_dados->>'data_movimento','')::timestamptz,now()),coalesce(nullif(_dados->>'motivo',''),'Recebimento físico'),coalesce(_dados->>'retirado_por',''),coalesce(_dados->>'observacoes',''),auth.uid()); IF res IS NOT NULL THEN UPDATE devolucao_reservas SET status='retirada',updated_at=now() WHERE id=res; END IF; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('devolucao',d.id,_tipo,_quantidade||' '||i.unidade||' - '||i.descricao,auth.uid()); RETURN _operacao; END $$;
REVOKE ALL ON FUNCTION public.movimentar_devolucao(uuid,uuid,text,numeric,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.movimentar_devolucao(uuid,uuid,text,numeric,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.alocar_devolucao(_item uuid,_numero int,_quantidade numeric,_local text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i devolucao_itens; p uuid; received numeric; allocated numeric; BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO i FROM devolucao_itens WHERE id=_item AND ativo FOR UPDATE; IF NOT FOUND OR NOT i.retorno_fisico THEN RAISE EXCEPTION 'Item sem retorno físico'; END IF; PERFORM 1 FROM devolucoes WHERE id=i.devolucao_id FOR UPDATE; IF EXISTS(SELECT 1 FROM devolucao_movimentos WHERE item_id=_item AND tipo='saida') OR EXISTS(SELECT 1 FROM devolucao_reservas WHERE item_id=_item AND status='ativa') THEN RAISE EXCEPTION 'Atribuição preservada após reserva ou retirada'; END IF; SELECT coalesce(sum(quantidade),0) INTO received FROM devolucao_movimentos WHERE item_id=_item AND tipo='entrada'; INSERT INTO devolucao_pallets(devolucao_id,numero,localizacao,created_by) VALUES(i.devolucao_id,_numero,_local,auth.uid()) ON CONFLICT(devolucao_id,numero) DO UPDATE SET localizacao=EXCLUDED.localizacao RETURNING id INTO p; SELECT coalesce(sum(quantidade),0) INTO allocated FROM devolucao_alocacoes WHERE item_id=_item AND pallet_id<>p; IF _quantidade IS NULL OR _quantidade<=0 OR allocated+_quantidade>received THEN RAISE EXCEPTION 'Pallet excede quantidade recebida'; END IF; INSERT INTO devolucao_alocacoes(pallet_id,item_id,quantidade,created_by) VALUES(p,_item,_quantidade,auth.uid()) ON CONFLICT(pallet_id,item_id) DO UPDATE SET quantidade=EXCLUDED.quantidade; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('devolucao',i.devolucao_id,'pallet',_numero||' - '||_quantidade||' '||i.unidade,auth.uid()); RETURN p; END $$;
REVOKE ALL ON FUNCTION public.alocar_devolucao(uuid,int,numeric,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.alocar_devolucao(uuid,int,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.reservar_devolucao(_id uuid,_item uuid,_quantidade numeric,_dados jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i devolucao_itens; saldo numeric; reserved numeric; pal uuid:=nullif(_dados->>'pallet_id','')::uuid; available numeric; BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO i FROM devolucao_itens WHERE id=_item AND ativo FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Item inexistente'; END IF; PERFORM 1 FROM devolucoes WHERE id=i.devolucao_id AND prestacao='enviada' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Prestação de contas pendente'; END IF; IF EXISTS(SELECT 1 FROM devolucao_reservas WHERE id=_id) THEN IF NOT EXISTS(SELECT 1 FROM devolucao_reservas WHERE id=_id AND item_id=_item AND quantidade=_quantidade AND pallet_id IS NOT DISTINCT FROM pal) THEN RAISE EXCEPTION 'Reserva reutilizada com dados diferentes'; END IF; RETURN _id; END IF; SELECT coalesce(sum(CASE WHEN tipo='entrada' THEN quantidade ELSE -quantidade END),0) INTO saldo FROM devolucao_movimentos WHERE item_id=_item; SELECT coalesce(sum(quantidade),0) INTO reserved FROM devolucao_reservas WHERE item_id=_item AND status='ativa'; IF _quantidade IS NULL OR _quantidade<=0 OR _quantidade>saldo-reserved THEN RAISE EXCEPTION 'Reserva superior ao saldo disponível'; END IF; IF pal IS NOT NULL THEN SELECT a.quantidade-coalesce((SELECT sum(quantidade) FROM devolucao_movimentos WHERE item_id=_item AND pallet_id=pal AND tipo='saida'),0)-coalesce((SELECT sum(quantidade) FROM devolucao_reservas WHERE item_id=_item AND pallet_id=pal AND status='ativa'),0) INTO available FROM devolucao_alocacoes a WHERE item_id=_item AND pallet_id=pal; IF available IS NULL OR _quantidade>available THEN RAISE EXCEPTION 'Saldo insuficiente neste pallet'; END IF; ELSIF EXISTS(SELECT 1 FROM devolucao_alocacoes WHERE item_id=_item) THEN RAISE EXCEPTION 'Escolha o pallet'; END IF; INSERT INTO devolucao_reservas(id,item_id,pallet_id,coleta_ref,quantidade,motivo,registrado_por) VALUES(_id,_item,pal,nullif(_dados->>'coleta_ref','')::uuid,_quantidade,coalesce(_dados->>'motivo','Reserva para coleta'),auth.uid()); INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('devolucao',i.devolucao_id,'reserva',_quantidade||' '||i.unidade,auth.uid()); RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.reservar_devolucao(uuid,uuid,numeric,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reservar_devolucao(uuid,uuid,numeric,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.liberar_reserva_devolucao(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r devolucao_reservas; did uuid; BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT devolucao_id INTO did FROM devolucao_itens WHERE id=(SELECT item_id FROM devolucao_reservas WHERE id=_id); PERFORM 1 FROM devolucao_itens WHERE id=(SELECT item_id FROM devolucao_reservas WHERE id=_id) FOR UPDATE; SELECT * INTO r FROM devolucao_reservas WHERE id=_id FOR UPDATE; IF r.status='retirada' THEN RAISE EXCEPTION 'Reserva já retirada'; END IF; IF r.status='liberada' THEN RETURN; END IF; UPDATE devolucao_reservas SET status='liberada',updated_at=now() WHERE id=_id; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('devolucao',did,'reserva_liberada','Sem saída de estoque',auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.liberar_reserva_devolucao(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.liberar_reserva_devolucao(uuid) TO authenticated;